sql.where:
R.DEL_DT IS NULL

	AND R.PRGRM_TYPE_CD = #{prgrmTypeCd}


	AND R.RSVT_YMD >= #{startLrnYmd}


	AND R.RSVT_YMD <= #{endLrnYmd}




			AND R.SCHL_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND P.PRGRM_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (
				R.SCHL_NM LIKE CONCAT('%', #{searchKeyword}, '%')
				OR P.PRGRM_NM LIKE CONCAT('%', #{searchKeyword}, '%')
			)

mapper.select:
SELECT
FROM EDU_RSVT_MST R LEFT JOIN EDU_PRGRM_MST P ON P.PRGRM_SN = R.PRGRM_SN AND P.PRGRM_TYPE_CD = R.PRGRM_TYPE_CD
ORDER BY R.RSVT_YMD DESC, R.RSVT_SN DESC LIMIT #{offset}, #{limit}
